using System;using System.IO;using System.Collections.Generic;using UnityEditor;using UnityEngine;
public static class OpenRPGHouseSamplingPolicyV644{
 [Serializable]public class Item{public string guid;}
 [Serializable]public class Request{public string output;public Item[] textures;}
 [Serializable]public class Row{public string guid,format,graphics_format,filter,wrap_u,wrap_v;public int aniso,mips,width,height;public float mip_bias;public bool source_texture_settings_unchanged;}
 [Serializable]public class Report{public string unity_version,graphics_api,quality_anisotropy,quality_name;public int quality_level,global_mipmap_limit;public Row[] textures;public bool full_import=false;}
 public static void Export(){var args=Environment.GetCommandLineArgs();int a=Array.IndexOf(args,"--openrpg-manifest");if(a<0)throw new Exception("Manifest absent");var r=JsonUtility.FromJson<Request>(File.ReadAllText(args[a+1]));if(File.Exists(r.output)||r.textures.Length!=18)throw new Exception("Preserve evidence; 18 source textures required");var rows=new List<Row>();foreach(var item in r.textures){var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(AssetDatabase.GUIDToAssetPath(item.guid));if(tex==null)throw new Exception("Texture absent");string before=EditorJsonUtility.ToJson(tex,true);rows.Add(new Row{guid=item.guid,format=tex.format.ToString(),graphics_format=tex.graphicsFormat.ToString(),filter=tex.filterMode.ToString(),wrap_u=tex.wrapModeU.ToString(),wrap_v=tex.wrapModeV.ToString(),aniso=tex.anisoLevel,mips=tex.mipmapCount,width=tex.width,height=tex.height,mip_bias=tex.mipMapBias,source_texture_settings_unchanged=before==EditorJsonUtility.ToJson(tex,true)});}int q=QualitySettings.GetQualityLevel();File.WriteAllText(r.output,JsonUtility.ToJson(new Report{unity_version=Application.unityVersion,graphics_api=SystemInfo.graphicsDeviceType.ToString(),quality_anisotropy=QualitySettings.anisotropicFiltering.ToString(),quality_name=QualitySettings.names[q],quality_level=q,global_mipmap_limit=QualitySettings.globalTextureMipmapLimit,textures=rows.ToArray()},true));}
}
